#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-boundaries.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
// verify-boundaries — consolidated import / module-boundary gate.
//
// One file, four sub-checks. Each sub-check is a self-contained boundary
// rule that no-ops green when its trigger shape is absent:
//   - no-server-imports        G-CLIENT-SERVER-BOUNDARY: a `"use client"`
//                              module's import-closure never reaches a
//                              server-only layer (src/db/*, repositories/,
//                              feature services|handlers, `server-only`).
//                              No-op when the repo has no src/.
//   - no-cross-feature-imports  src/features/<A>/… reaches src/features/<B>/
//                              only through B's public surface (index barrel).
//                              No-op when there is no src/features/.
//   - no-undeclared-deps        every import specifier in src/ traces to a
//                              declared dependency / built-in / workspace /
//                              alias / relative path. No-op when no src/.
//   - firebase-boundary         server-only Admin SDK; no client Firebase SDK,
//                              no banned client files, no NEXT_PUBLIC_ secrets,
//                              no email-allowlist authorization. No-op when the
//                              repo declares no firebase dependency.
//
// Usage:
//   node verify-boundaries.mjs                          run all four (fail iff any fails)
//   node verify-boundaries.mjs --check no-server-imports
//   node verify-boundaries.mjs --check no-cross-feature-imports
//   node verify-boundaries.mjs --check no-undeclared-deps
//   node verify-boundaries.mjs --check firebase-boundary
//
// Exit: 0 when every selected check is green; 1 when any check fails; 2 on an
// unknown --check name.
//
// Pure Node + zero dependencies. `runAudit` (the no-server-imports audit) is
// exported so a selftest can drive it against a temp fixture without spawning.

import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { basename, dirname, join, normalize, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { builtinModules } from "node:module";
import process from "node:process";

const __filename = fileURLToPath(import.meta.url);
const SCRIPT_DIR = dirname(__filename);
const ROOT_DIR = resolve(SCRIPT_DIR, "..", "..");

// ════════════════════════════════════════════════════════════════════════
// CHECK 1 — no-server-imports (G-CLIENT-SERVER-BOUNDARY)
// ════════════════════════════════════════════════════════════════════════

const VIOLATION_MESSAGE_PREFIX =
  "G-CLIENT-SERVER-BOUNDARY violation: server-only code is reachable from a client (`\"use client\"`) module.";

/** Path (relative to src/, forward-slashed) of a server-only LAYER. */
export function isServerOnlyLayerPath(relFromSrc) {
  const p = relFromSrc.split(sep).join("/");
  if (/^db\//.test(p)) return true; // DB client + RLS bridge + migrations
  if (/(^|\/)repositories\//.test(p)) return true; // repositories anywhere
  if (/^features\/[^/]+\/(services|handlers)\//.test(p)) return true; // feature server logic
  return false;
}

const IMPORT_SPECIFIER_RE = /(?:from|import|require)\s*\(?\s*["']([^"']+)["']/g;
const USE_CLIENT_RE = /^\s*["']use client["']\s*;?\s*$/;
const SERVER_ONLY_IMPORT_RE = /["'](server-only|server-cli-only)["']/;

/** Recursively collect every .ts/.tsx file under `dir`. */
export function collectFiles(dir) {
  const result = [];
  const stack = [dir];
  while (stack.length > 0) {
    const current = stack.pop();
    let entries;
    try {
      entries = readdirSync(current);
    } catch {
      continue;
    }
    for (const entry of entries) {
      const full = join(current, entry);
      let stats;
      try {
        stats = statSync(full);
      } catch {
        continue;
      }
      if (stats.isDirectory()) {
        if (["node_modules", ".next", "dist", "build"].includes(entry)) continue;
        stack.push(full);
      } else if (stats.isFile() && (entry.endsWith(".ts") || entry.endsWith(".tsx"))) {
        result.push(full);
      }
    }
  }
  return result;
}

/** Resolve a local import specifier to an absolute file path, or null for bare/external. */
export function resolveSpecifier(specifier, fromDir, srcDir) {
  let base;
  if (specifier.startsWith("@/")) base = join(srcDir, specifier.slice(2));
  else if (specifier.startsWith(".")) base = resolve(fromDir, specifier);
  else return null; // bare package, node:, server-only, etc.
  const candidates = [
    base,
    `${base}.ts`,
    `${base}.tsx`,
    join(base, "index.ts"),
    join(base, "index.tsx"),
  ];
  for (const c of candidates) {
    try {
      if (existsSync(c) && statSync(c).isFile()) return c;
    } catch {
      /* ignore */
    }
  }
  return null;
}

/** Parse one file into { useClient, serverOnlyImport, imports[] (raw specifiers) }. */
export function parseModule(content) {
  const lines = content.split("\n");
  let useClient = false;
  // "use client" must be the first statement (allow leading comments/blank lines).
  for (const line of lines) {
    const t = line.trim();
    if (t === "" || t.startsWith("//") || t.startsWith("/*") || t.startsWith("*")) continue;
    if (USE_CLIENT_RE.test(line)) useClient = true;
    break;
  }
  const serverOnlyImport = SERVER_ONLY_IMPORT_RE.test(content);
  const imports = [];
  for (const line of lines) {
    const codeIdx = line.indexOf("//");
    const code = codeIdx === -1 ? line : line.slice(0, codeIdx);
    IMPORT_SPECIFIER_RE.lastIndex = 0;
    let m;
    while ((m = IMPORT_SPECIFIER_RE.exec(code)) !== null) imports.push(m[1]);
  }
  return { useClient, serverOnlyImport, imports };
}

/**
 * Build the client import-closure and flag any server-only module inside it.
 * @returns {{ entry: string, serverModule: string }[]} violations (src-relative paths)
 */
export function findViolations(srcDir) {
  const files = collectFiles(srcDir);
  const mods = new Map(); // abs -> parsed
  for (const f of files) {
    try {
      mods.set(f, parseModule(readFileSync(f, "utf8")));
    } catch {
      /* unreadable -> skip */
    }
  }
  const relSrc = (abs) => relative(srcDir, abs).split(sep).join("/");
  const isServerOnly = (abs) =>
    mods.get(abs)?.serverOnlyImport === true || isServerOnlyLayerPath(relSrc(abs));

  const violations = [];
  for (const [abs, parsed] of mods) {
    if (!parsed.useClient) continue;
    // BFS the closure from this client entry.
    const seen = new Set([abs]);
    const stack = [abs];
    while (stack.length > 0) {
      const cur = stack.pop();
      const curParsed = mods.get(cur);
      if (!curParsed) continue;
      for (const spec of curParsed.imports) {
        const target = resolveSpecifier(spec, dirname(cur), srcDir);
        if (!target || seen.has(target)) continue;
        seen.add(target);
        if (isServerOnly(target)) {
          violations.push({ entry: relSrc(abs), serverModule: relSrc(target) });
          continue; // don't traverse into server-only code from here
        }
        stack.push(target);
      }
    }
  }
  return violations;
}

/** Main entry — audits `<rootDir>/src` and returns the exit code. */
export function runAudit(rootDir = ROOT_DIR) {
  const srcDir = join(rootDir, "src");
  if (!existsSync(srcDir)) {
    process.stdout.write("[verify-no-server-imports] PASS — no src/ in this repo.\n");
    return 0;
  }
  const violations = findViolations(srcDir);
  if (violations.length === 0) {
    process.stdout.write(
      "[verify-no-server-imports] PASS — no server-only module is reachable from a `\"use client\"` entry.\n",
    );
    return 0;
  }
  process.stderr.write(`${VIOLATION_MESSAGE_PREFIX}\n`);
  process.stderr.write(
    "The client→server bridge is a Server Action (`actions/*.action.ts`) or an HTTP route handler — not a direct import of src/db, repositories, services, or handlers.\n\nViolations:\n",
  );
  for (const v of violations) {
    process.stderr.write(`  client \`${v.entry}\` reaches server-only \`${v.serverModule}\`\n`);
  }
  process.stderr.write(
    "\nRule: PROJECT_ARCHITECTURE.yaml `single_app_shape` (RSC server/client boundary). Non-overridable.\n",
  );
  return 1;
}

function checkNoServerImports() {
  return runAudit();
}

export const _constants = { VIOLATION_MESSAGE_PREFIX };

// ════════════════════════════════════════════════════════════════════════
// CHECK 2 — no-cross-feature-imports
// ════════════════════════════════════════════════════════════════════════

/**
 * Extracts every relative import specifier (those starting with `.`)
 * from a TS/JS source string. Strips // line comments first.
 *
 * @param {string} src
 * @returns {string[]}
 */
export function extractRelativeSpecifiers(src) {
  const stripped = src.split("\n").map((l) => l.replace(/(?<!:)\/\/.*$/, "")).join("\n");
  const re = /(?:from|import|require)\s*\(?\s*["'](\.\.?\/[^"']+)["']/g;
  const out = new Set();
  let m;
  while ((m = re.exec(stripped)) !== null) out.add(m[1]);
  return [...out];
}

/**
 * Maps a (sourceFile, relativeSpecifier) pair to a normalized absolute
 * path. Strips any trailing `/index` plus extension so the gate's match
 * can compare to the feature root directory.
 *
 * @param {string} sourceFile
 * @param {string} spec
 * @returns {string}
 */
export function resolveImportTarget(sourceFile, spec) {
  const abs = normalize(resolve(dirname(sourceFile), spec));
  return abs.replace(/\.(?:ts|tsx|mts|cts|js|jsx|mjs)$/, "").replace(/\/index$/, "");
}

/**
 * Given an absolute path, returns the feature name (the slug between
 * `features/` and the next `/`) or null when the path is not under any
 * feature folder.
 *
 * @param {string} absPath
 * @param {string} featuresRoot
 * @returns {string | null}
 */
export function featureNameFor(absPath, featuresRoot) {
  const prefix = featuresRoot.endsWith("/") ? featuresRoot : featuresRoot + "/";
  if (!absPath.startsWith(prefix)) return null;
  const rest = absPath.slice(prefix.length);
  const slash = rest.indexOf("/");
  return slash === -1 ? rest : rest.slice(0, slash);
}

/**
 * Decides whether (sourceFeature, importedAbsPath) is an allowed cross-
 * feature import (target is the public surface — feature root) vs a
 * violation (target reaches into internals).
 *
 * @param {string} sourceFeature
 * @param {string} importedAbsPath
 * @param {string} featuresRoot
 * @returns {{ kind: "same-feature"|"public-surface"|"internals", targetFeature: string | null }}
 */
export function classifyCrossFeatureImport(sourceFeature, importedAbsPath, featuresRoot) {
  const targetFeature = featureNameFor(importedAbsPath, featuresRoot);
  if (targetFeature === null) return { kind: "same-feature", targetFeature: null }; // not into another feature
  if (targetFeature === sourceFeature) return { kind: "same-feature", targetFeature };
  const prefix = featuresRoot.endsWith("/") ? featuresRoot : featuresRoot + "/";
  const expectedRoot = prefix + targetFeature;
  if (importedAbsPath === expectedRoot) return { kind: "public-surface", targetFeature };
  return { kind: "internals", targetFeature };
}

function checkNoCrossFeatureImports(sourceRoot = sourceRootFromArgv(), repoRoot = process.cwd()) {
  const SOURCE_ROOT = sourceRoot;
  const REPO_ROOT = repoRoot;
  const absRoot = join(REPO_ROOT, SOURCE_ROOT);
  const FEATURES_DIR = join(absRoot, "features");

  const SKIP_DIRS = new Set([
    "node_modules", ".next", ".turbo", "dist", "build", "out", ".git",
    "coverage", "test-results", "playwright-report",
  ]);
  const SCANNABLE_EXTS = new Set([".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs"]);

  const violations = [];

  function walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        walk(join(dir, entry.name));
        continue;
      }
      const idx = entry.name.lastIndexOf(".");
      if (idx === -1) continue;
      if (!SCANNABLE_EXTS.has(entry.name.slice(idx))) continue;
      if (entry.name.endsWith(".d.ts")) continue;
      const file = join(dir, entry.name);
      const sourceFeature = featureNameFor(file, FEATURES_DIR);
      if (sourceFeature === null) continue; // file outside features/
      let src;
      try { src = readFileSync(file, "utf8"); } catch { continue; }
      const specs = extractRelativeSpecifiers(src);
      for (const spec of specs) {
        const target = resolveImportTarget(file, spec);
        const cls = classifyCrossFeatureImport(sourceFeature, target, FEATURES_DIR);
        if (cls.kind === "internals") {
          violations.push({
            file: relative(REPO_ROOT, file),
            specifier: spec,
            sourceFeature,
            targetFeature: cls.targetFeature,
            allowed: `import from ${SOURCE_ROOT}/features/${cls.targetFeature} (its index.ts barrel) instead`,
          });
        }
      }
    }
  }

  if (!existsSync(absRoot)) {
    process.stdout.write(`✅ verify-no-cross-feature-imports — no ${SOURCE_ROOT}/ in this repo; nothing to check.\n`);
    return 0;
  }
  if (!existsSync(FEATURES_DIR)) {
    process.stdout.write(`✅ verify-no-cross-feature-imports — no ${SOURCE_ROOT}/features/ folder; nothing to check.\n`);
    return 0;
  }
  walk(FEATURES_DIR);
  if (violations.length === 0) {
    process.stdout.write(`✅ verify-no-cross-feature-imports — every cross-feature import goes through the public surface.\n`);
    return 0;
  }
  process.stderr.write(`❌ verify-no-cross-feature-imports: ${violations.length} cross-feature internals import(s)\n\n`);
  for (const v of violations) {
    process.stderr.write(`  ${v.file}: feature "${v.sourceFeature}" imports "${v.specifier}" (reaches into feature "${v.targetFeature}" internals)\n`);
    process.stderr.write(`     allowed: ${v.allowed}\n`);
  }
  process.stderr.write(
    `\nFeatures are self-contained. Cross-feature imports go through the public surface (the target feature's index.ts barrel). If you need an internal symbol, either move the symbol to the target feature's public surface, or move the consuming code into the target feature.\n`,
  );
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CHECK 3 — no-undeclared-deps
// ════════════════════════════════════════════════════════════════════════

const BUILTINS = new Set([...builtinModules, ...builtinModules.map((m) => `node:${m}`)]);

/**
 * tsconfig.json compilerOptions.paths aliases → bare prefixes treated as
 * internal (NOT undeclared deps). `"@/*": ["./src/*"]` → prefix `@/`.
 */
function tsconfigAliasPrefixes(repoRoot) {
  const tsconfigPath = join(repoRoot, "tsconfig.json");
  if (!existsSync(tsconfigPath)) return [];
  try {
    const raw = readFileSync(tsconfigPath, "utf8").replace(/\/\/.*$/gm, "");
    const paths = JSON.parse(raw)?.compilerOptions?.paths ?? {};
    return Object.keys(paths).map((k) => k.replace(/\*+$/, "")).filter(Boolean);
  } catch {
    return [];
  }
}

/**
 * Extracts the package-root name from a bare specifier.
 * `foo` → `foo`; `foo/sub/path` → `foo`; `@scope/foo` → `@scope/foo`;
 * `@scope/foo/sub` → `@scope/foo`.
 *
 * @param {string} spec
 * @returns {string}
 */
export function rootPackageName(spec) {
  if (spec.startsWith("@")) {
    const parts = spec.split("/");
    return parts.slice(0, 2).join("/");
  }
  return spec.split("/")[0];
}

/**
 * Parses every import / require / dynamic-import specifier from a source
 * string. Strips // line comments before matching.
 *
 * @param {string} src
 * @returns {string[]}
 */
export function extractSpecifiers(src) {
  const stripped = src
    .split("\n")
    .map((line) => line.replace(/(?<!:)\/\/.*$/, ""))
    .join("\n");
  const out = [];
  const re = /(?:^|[\s;{(=,])(?:import|require)\s*\(?\s*["']([^"']+)["']/g;
  let m;
  while ((m = re.exec(stripped)) !== null) out.push(m[1]);
  const re2 = /\bfrom\s*["']([^"']+)["']/g;
  while ((m = re2.exec(stripped)) !== null) out.push(m[1]);
  return [...new Set(out)];
}

/**
 * Walks up from `fromDir` looking for the nearest `package.json` and
 * returns the merged set of declared package names.
 *
 * @param {string} fromDir
 * @param {string} stopAt
 * @returns {Set<string>}
 */
export function declaredDepsForFile(fromDir, stopAt) {
  let dir = fromDir;
  while (true) {
    const pkgPath = join(dir, "package.json");
    if (existsSync(pkgPath)) {
      try {
        const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
        const set = new Set();
        for (const k of ["dependencies", "devDependencies", "peerDependencies", "optionalDependencies"]) {
          if (pkg[k]) for (const name of Object.keys(pkg[k])) set.add(name);
        }
        return set;
      } catch { /* fall through */ }
    }
    if (dir === stopAt || dir === dirname(dir)) return new Set();
    dir = dirname(dir);
  }
}

/**
 * Reads pnpm-workspace.yaml's `packages:` globs (if present) and
 * resolves to the set of declared workspace package names.
 *
 * @param {string} repoRoot
 * @returns {Set<string>}
 */
export function workspacePackageNames(repoRoot) {
  const wsPath = join(repoRoot, "pnpm-workspace.yaml");
  if (!existsSync(wsPath)) return new Set();
  const txt = readFileSync(wsPath, "utf8");
  const out = new Set();
  const lines = txt.split("\n").map((l) => l.trim());
  const inPackages = lines.findIndex((l) => l.startsWith("packages:")) !== -1;
  if (!inPackages) return out;
  const globs = lines
    .filter((l) => l.startsWith("- "))
    .map((l) => l.slice(2).replace(/^["']|["']$/g, ""));
  for (const glob of globs) {
    const bareDir = glob.replace(/\/\*+$/, "");
    const parent = join(repoRoot, bareDir);
    if (!existsSync(parent)) continue;
    try {
      for (const entry of readdirSync(parent, { withFileTypes: true })) {
        if (!entry.isDirectory()) continue;
        const pkgPath = join(parent, entry.name, "package.json");
        if (!existsSync(pkgPath)) continue;
        try {
          const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
          if (pkg.name) out.add(pkg.name);
        } catch { /* skip */ }
      }
    } catch { /* skip */ }
  }
  return out;
}

function checkNoUndeclaredDeps(sourceRoot = sourceRootFromArgv(), repoRoot = process.cwd()) {
  const SOURCE_ROOT = sourceRoot;
  const REPO_ROOT = repoRoot;
  const absRoot = join(REPO_ROOT, SOURCE_ROOT);

  const SKIP_DIRS = new Set([
    "node_modules", ".next", ".turbo", "dist", "build", "out", ".git",
    "coverage", "test-results", "playwright-report",
  ]);
  const SCANNABLE_EXTS = new Set([".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"]);

  const workspaces = workspacePackageNames(REPO_ROOT);
  const tsAliasPrefixes = tsconfigAliasPrefixes(REPO_ROOT);
  const violations = [];

  function walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (SKIP_DIRS.has(entry.name)) continue;
        walk(join(dir, entry.name));
        continue;
      }
      const idx = entry.name.lastIndexOf(".");
      if (idx === -1) continue;
      if (!SCANNABLE_EXTS.has(entry.name.slice(idx))) continue;
      if (entry.name.endsWith(".d.ts")) continue;
      const file = join(dir, entry.name);
      let src;
      try { src = readFileSync(file, "utf8"); } catch { continue; }
      const specs = extractSpecifiers(src);
      if (specs.length === 0) continue;
      const deps = declaredDepsForFile(dirname(file), REPO_ROOT);
      for (const spec of specs) {
        if (spec.startsWith(".") || spec.startsWith("/")) continue;
        if (spec.startsWith("#")) continue;
        if (tsAliasPrefixes.some((p) => spec === p.replace(/\/$/, "") || spec.startsWith(p))) continue;
        if (BUILTINS.has(spec) || BUILTINS.has(`node:${spec}`)) continue;
        const root = rootPackageName(spec);
        if (deps.has(root)) continue;
        if (workspaces.has(root)) continue;
        violations.push({ file: relative(REPO_ROOT, file), specifier: spec, root });
      }
    }
  }

  if (!existsSync(absRoot)) {
    process.stdout.write(
      `✅ verify-no-undeclared-deps — no ${SOURCE_ROOT}/ in this repo; nothing to check.\n`,
    );
    return 0;
  }
  walk(absRoot);
  if (violations.length === 0) {
    process.stdout.write(
      `✅ verify-no-undeclared-deps — every import specifier in ${SOURCE_ROOT}/ traces to a declared dependency.\n`,
    );
    return 0;
  }
  process.stderr.write(`❌ verify-no-undeclared-deps: ${violations.length} undeclared specifier(s)\n\n`);
  for (const v of violations) {
    process.stderr.write(`  ${v.file}: imports "${v.specifier}" (package "${v.root}" not in package.json)\n`);
  }
  process.stderr.write(
    `\nAdd the missing packages to dependencies/devDependencies in the nearest package.json, or fix the import to use a relative path / workspace alias / Node built-in.\n`,
  );
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CHECK 4 — firebase-boundary (GOOGLE_FIREBASE_STANDARDS)
// ════════════════════════════════════════════════════════════════════════

function checkFirebaseBoundary(rootArg = ".") {
  const GREEN = "\x1b[32m";
  const RED = "\x1b[31m";
  const RESET = "\x1b[0m";
  const NAME = "verify-firebase-boundary";

  const SKIP_DIRS = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "coverage", "out", ".archive"]);

  function* walk(dir) {
    for (const ent of readdirSync(dir, { withFileTypes: true })) {
      if (ent.isDirectory()) {
        if (!SKIP_DIRS.has(ent.name)) yield* walk(join(dir, ent.name));
      } else yield join(dir, ent.name);
    }
  }

  const root = resolve(process.cwd(), rootArg);
  const all = existsSync(root) ? [...walk(root)] : [];

  const usesFirebase = all
    .filter((f) => basename(f) === "package.json")
    .some((f) => {
      try {
        const p = JSON.parse(readFileSync(f, "utf8"));
        const deps = { ...p.dependencies, ...p.devDependencies };
        return Object.keys(deps || {}).some((d) => d === "firebase" || d === "firebase-admin" || d.startsWith("@firebase/"));
      } catch { return false; }
    });

  if (!usesFirebase) {
    process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — no firebase dependency; nothing to verify.\n`);
    return 0;
  }

  const violations = [];
  let scanned = 0;

  for (const f of all) {
    const rel = relative(root, f);
    if (/src\/lib\/firebase-client\.[a-z]+$/.test(rel)) violations.push({ rel, rule: "banned file — client-side Firebase module (server-only Admin SDK is the sole path)" });
    if (/src\/middleware\.ts$/.test(rel)) violations.push({ rel, rule: "banned file — use src/proxy.ts, not src/middleware.ts" });

    const isCode = /\.(ts|tsx|mts|js|mjs|jsx)$/.test(rel);
    const isEnv = /(^|\/)\.env[^/]*$/.test(rel);
    if (!isCode && !isEnv) continue;
    scanned++;
    const text = readFileSync(f, "utf8");

    if (isCode) {
      for (const m of text.matchAll(/from\s+['"]firebase\/([a-z-]+)['"]/g)) {
        violations.push({ rel, rule: `client Firebase SDK import "firebase/${m[1]}" — ZERO client-side SDK; use firebase-admin server-side` });
      }
    }
    for (const m of text.matchAll(/NEXT_PUBLIC_FIREBASE_[A-Z0-9_]*/g)) {
      violations.push({ rel, rule: `${m[0]} — client SDK is banned, so no public firebase config vars` });
    }
    for (const m of text.matchAll(/NEXT_PUBLIC_[A-Z0-9_]*(SECRET|PRIVATE|TOKEN|PASSWORD|SERVICE_ACCOUNT)[A-Z0-9_]*/g)) {
      violations.push({ rel, rule: `${m[0]} — NEXT_PUBLIC_ must never carry a server-only secret` });
    }
    for (const m of text.matchAll(/\b(ADMIN_EMAILS|ALLOWED_EMAILS)\b/g)) {
      violations.push({ rel, rule: `${m[1]} — email-allowlist authorization is banned; use the permission-slug catalog` });
    }
  }

  const dedup = [...new Map(violations.map((v) => [v.rel + v.rule, v])).values()];
  if (dedup.length === 0) {
    process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — firebase repo; ${scanned} file(s) scanned; boundary clean.\n`);
    return 0;
  }
  process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${dedup.length} violation(s)\n`);
  for (const v of dedup) process.stderr.write(`  [${v.rel}] ${v.rule}\n`);
  process.stderr.write(`Per GOOGLE_FIREBASE_STANDARDS.yaml — server-side Admin SDK only; permission-slug authorization.\n`);
  return 1;
}

// ════════════════════════════════════════════════════════════════════════
// CLI dispatch
// ════════════════════════════════════════════════════════════════════════

// The cross-feature + undeclared checks accept an optional positional source
// root (legacy `argv[2]`, default "src"). When a --check flag is present the
// positional arg lives after it; otherwise it is the first non-flag arg.
function sourceRootFromArgv() {
  const args = process.argv.slice(2);
  const checkIdx = args.indexOf("--check");
  const positional = args.filter((a, i) => {
    if (a === "--check") return false;
    if (checkIdx !== -1 && i === checkIdx + 1) return false;
    return !a.startsWith("--");
  });
  return positional[0] || "src";
}

const CHECKS = {
  "no-server-imports": checkNoServerImports,
  "no-cross-feature-imports": checkNoCrossFeatureImports,
  "no-undeclared-deps": checkNoUndeclaredDeps,
  "firebase-boundary": checkFirebaseBoundary,
};

export function isCliInvocation(importMetaUrl, argv1) {
  if (argv1 === undefined || argv1 === "") return false;
  return importMetaUrl === pathToFileURL(argv1).href;
}

function main() {
  const args = process.argv.slice(2);
  const checkIdx = args.indexOf("--check");
  const only = checkIdx !== -1 ? args[checkIdx + 1] : null;

  const names = only ? [only] : Object.keys(CHECKS);
  let failures = 0;
  for (const name of names) {
    const fn = CHECKS[name];
    if (!fn) {
      process.stderr.write(`verify-boundaries: unknown check "${name}" (expected one of: ${Object.keys(CHECKS).join(", ")})\n`);
      process.exit(2);
    }
    if (fn() !== 0) failures += 1;
  }
  process.exit(failures > 0 ? 1 : 0);
}

if (isCliInvocation(import.meta.url, process.argv[1])) {
  main();
}
